import type { EngineInterface, Register } from 'claude-code'
import { match, render, validate, worst, type Tripwire } from './match.ts'
import { SEED } from './tripwires.ts'

/**
 * tripwire: lessons that fire at the moment of action.
 *
 *   remind  the call runs; the lesson is attached to its result for the agent
 *   ask     the user is asked first; no answer means no
 *   block   the call is refused and the agent is told why
 *
 * Built-in lessons live in hooks/tripwires.ts; personal ones in
 * ~/.claude/tripwires.json. A broken file never stops work: bad entries are
 * skipped and reported by /tripwires.
 */

const CACHE_MS = 30_000
let cache: { at: number; wires: Tripwire[]; problems: string[] } | null = null

async function loadWires($: EngineInterface) {
  if (cache && Date.now() - cache.at < CACHE_MS) return cache
  const seed = validate(SEED)
  const wires: Tripwire[] = [...seed.wires]
  const problems: string[] = seed.problems.map(p => `built-in: ${p}`)
  const home = await $.process.run(['printenv', 'HOME']).then(r => r.stdout.trim(), () => '')
  const files = home ? [`${home}/.claude/tripwires.json`] : []
  for (const file of files) {
    const text = await $.fs.read(file).catch(() => null)
    if (typeof text !== 'string') continue
    try {
      const result = validate(JSON.parse(text))
      wires.push(...result.wires)
      problems.push(...result.problems.map(p => `${file}: ${p}`))
    } catch (err) {
      problems.push(`${file}: not valid JSON (${String(err)})`)
    }
  }
  cache = { at: Date.now(), wires, problems }
  return cache
}

type Stats = Record<string, { fired: number; last: string }>

async function record($: EngineInterface, ids: string[]) {
  try {
    const stats = ((await $.store.get('stats')) ?? {}) as Stats
    const now = new Date().toISOString()
    for (const id of ids) stats[id] = { fired: (stats[id]?.fired ?? 0) + 1, last: now }
    await $.store.set('stats', stats)
  } catch {
    // Counting is a nicety; never let it interfere with the tool call.
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'tripwires', description: 'List tripwires, how often each fired, and any broken entries' })
    return next(e)
  })

  on('command.run', { command: 'tripwires' }, async $ => {
    cache = null
    const { wires, problems } = await loadWires($)
    const stats = ((await $.store.get('stats').catch(() => ({}))) ?? {}) as Stats
    const lines = wires.map(w => {
      const s = stats[w.id]
      return `${w.severity.padEnd(6)} ${w.id.padEnd(28)} ${s ? `fired ${s.fired}x, last ${s.last.slice(0, 10)}` : 'never fired'}`
    })
    return { text: [`${wires.length} tripwires`, ...lines, ...(problems.length ? ['', 'Problems:', ...problems] : [])].join('\n') }
  })

  on('tool.call', async ($, e, next) => {
    let fired
    try {
      const { wires } = await loadWires($)
      fired = match(wires, e.tool, e as unknown as Record<string, unknown>)
    } catch {
      return next(e) // tripwires are advice; a loading error must not stop work
    }
    if (fired.length === 0) return next(e)

    const severity = worst(fired)
    const text = render(fired)
    void record($, fired.map(f => f.wire.id))

    if (severity === 'block') {
      $.ui.toast(`Tripwire blocked ${e.tool}: ${fired.map(f => f.wire.id).join(', ')}`)
      return { deny: `${text}\nThis action was stopped by a tripwire. Fix the cause; do not retry it or work around it.` }
    }

    if (severity === 'ask') {
      let answer = ''
      try {
        answer = await $.ui.ask(`Tripwire: ${fired.map(f => f.wire.lesson).join(' / ')} Continue?`, {
          header: 'Tripwire',
          options: ['Stop', 'Continue'],
        })
      } catch {
        // Dismissed, or nobody to ask: an "ask" wire means not without a yes.
      }
      if (answer !== 'Continue') return { deny: `${text}\nThe user did not approve continuing.` }
    }

    // remind (and an approved ask): run it, then put the lesson in front of the agent.
    const ran = await next(e)
    if ('deny' in ran && ran.deny !== undefined) return ran
    $.ui.toast(`Tripwire: ${fired.map(f => f.wire.id).join(', ')}`)
    return { ...ran, context: [...(ran.context ?? []), text] } as typeof ran
  })
}

