/**
 * Pure matching logic, kept free of the engine so it can be tested directly.
 *
 * A tripwire is a lesson indexed by the ACTION that should trigger it, not by
 * topic. When an agent is about to make a matching tool call, the lesson fires
 * at that moment instead of hoping it was remembered from session start.
 */

export type Severity = 'remind' | 'ask' | 'block'

export type Tripwire = {
  id: string
  /** Regex on the tool name, e.g. "^Bash$" or "claude-in-chrome__navigate". */
  tool: string
  /** Regex tested against `field` of the tool input, or the whole input as JSON. */
  pattern: string
  /** Optional input field to test, e.g. "command", "file_path", "url". */
  field?: string
  /** Optional regex that, if it also matches, cancels the tripwire. */
  unless?: string
  severity: Severity
  lesson: string
  /** Where the lesson was learned, so it can be checked. */
  source?: string
  /** Never echo the matched text (for tripwires that match secrets). */
  redact?: boolean
}

export type Fired = { wire: Tripwire; matched: string }

const RANK: Record<Severity, number> = { remind: 0, ask: 1, block: 2 }

/** Compiles a pattern; a bad one disables that wire instead of throwing. */
function compile(source: string): RegExp | null {
  try {
    return new RegExp(source, 'i')
  } catch {
    return null
  }
}

export function validate(raw: unknown): { wires: Tripwire[]; problems: string[] } {
  const problems: string[] = []
  const list = Array.isArray(raw) ? raw : Array.isArray((raw as { tripwires?: unknown })?.tripwires) ? (raw as { tripwires: unknown[] }).tripwires : null
  if (!list) return { wires: [], problems: ['tripwires file must be an array or { "tripwires": [...] }'] }

  const wires: Tripwire[] = []
  for (const item of list) {
    const w = item as Partial<Tripwire>
    const id = typeof w.id === 'string' ? w.id : '(no id)'
    if (!w.id || !w.tool || !w.pattern || !w.lesson) {
      problems.push(`${id}: needs id, tool, pattern and lesson`)
      continue
    }
    if (w.severity && !(w.severity in RANK)) {
      problems.push(`${id}: severity must be remind, ask or block`)
      continue
    }
    if (!compile(w.tool) || !compile(w.pattern) || (w.unless && !compile(w.unless))) {
      problems.push(`${id}: invalid regex`)
      continue
    }
    wires.push({ ...w, severity: w.severity ?? 'remind' } as Tripwire)
  }
  return { wires, problems }
}

/** The text a tool call is tested against. */
export function haystack(input: Record<string, unknown>, field?: string): string {
  if (field) {
    const value = input[field]
    return typeof value === 'string' ? value : value == null ? '' : JSON.stringify(value)
  }
  // Every string in the input, raw. JSON.stringify would escape quotes, and a
  // pattern like "directory": "./" could then never match.
  const { tool: _tool, ...rest } = input
  const parts: string[] = []
  const walk = (v: unknown) => {
    if (typeof v === 'string') parts.push(v)
    else if (Array.isArray(v)) v.forEach(walk)
    else if (v && typeof v === 'object') Object.values(v).forEach(walk)
  }
  walk(rest)
  return parts.join('\n')
}

export function match(wires: readonly Tripwire[], toolName: string, input: Record<string, unknown>): Fired[] {
  const fired: Fired[] = []
  for (const wire of wires) {
    if (!compile(wire.tool)!.test(toolName)) continue
    const text = haystack(input, wire.field)
    const hit = compile(wire.pattern)!.exec(text)
    if (!hit) continue
    if (wire.unless && compile(wire.unless)!.test(text)) continue
    fired.push({ wire, matched: hit[0] })
  }
  return fired
}

export function worst(fired: readonly Fired[]): Severity | null {
  if (fired.length === 0) return null
  return fired.reduce<Severity>((w, f) => (RANK[f.wire.severity] > RANK[w] ? f.wire.severity : w), 'remind')
}

/** What the agent reads. The matched text is shown but capped, never a whole secret-bearing command. */
export function render(fired: readonly Fired[]): string {
  return fired
    .map(f => {
      const shown = f.wire.redact ? '[redacted]' : f.matched.length > 40 ? `${f.matched.slice(0, 12)}…` : f.matched
      return `⚡ TRIPWIRE [${f.wire.id}] (${f.wire.severity}) on "${shown}": ${f.wire.lesson}${f.wire.source ? ` (learned: ${f.wire.source})` : ''}`
    })
    .join('\n')
}

